function Modal({ open, onClose, children }) {
  const modalRef = useRef(null);

  useEffect(() => {
    if (open && modalRef.current) {
      modalRef.current.focus();
    }
  }, [open]);

  return (
    <Dialog 
      open={open} 
      onClose={onClose}
      ref={modalRef}
      tabIndex={-1}
    >
      {children}
    </Dialog>
  );
}
